def record_past_gate_ins(apps, schema_editor):
    """Give each indent already gated in the one arrival it had.

    Before arrivals existed a gate-in meant the whole purchase came at once,
    so the arrival carries every bought line in full, and it counts as
    received if the store already received the indent.
    """
    MaterialIndent = apps.get_model("maintenance", "MaterialIndent")
    MaterialIndentArrival = apps.get_model("maintenance", "MaterialIndentArrival")
    MaterialIndentArrivalLine = apps.get_model("maintenance", "MaterialIndentArrivalLine")

    for indent in MaterialIndent.objects.filter(status__in=["GATE_IN", "RECEIVED"]):
        arrival = MaterialIndentArrival.objects.create(
            indent=indent,
            arrival_no=1,
            vehicle_number=indent.gatein_vehicle_number,
            driver_name=indent.gatein_driver_name,
            driver_mobile=indent.gatein_driver_mobile,
            gate_in_by_id=indent.gate_in_by_id,
            gate_in_at=indent.gate_in_at or indent.updated_at,
            received_by_id=indent.received_by_id if indent.status == "RECEIVED" else None,
            received_at=(indent.received_at or indent.updated_at)
            if indent.status == "RECEIVED"
            else None,
            created_by_id=indent.gate_in_by_id,
            updated_by_id=indent.gate_in_by_id,
        )
        for item in indent.items.all():
            bought = item.quantity - item.issued_quantity
            if bought <= 0:
                continue
            MaterialIndentArrivalLine.objects.create(
                arrival=arrival,
                item=item,
                quantity=bought,
                created_by_id=indent.gate_in_by_id,
                updated_by_id=indent.gate_in_by_id,
            )
            item.arrived_quantity = bought
            item.save(update_fields=["arrived_quantity"])


